// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { computeGraphLayout } from "../../../main/frontend/graph-explorer/graph-layout-engine.ts";
import { computeSquareLayout } from "../../../main/frontend/graph-explorer/graph-layout-square.ts";
import { graphNodeSize } from "../../../main/frontend/graph-explorer/graph-geometry.ts";

const node = (id, x, y, extra = {}) => ({ id, kind: "iri", label: `Node ${id}`, x, y, ...extra });
const edge = (source, target) => ({ id: `${source}-${target}`, source, target, predicate: "urn:p", label: "p" });

function centre(positions, ids) {
  const xs = ids.map((id) => positions.get(id).x), ys = ids.map((id) => positions.get(id).y);
  return { x: (Math.min(...xs) + Math.max(...xs)) / 2, y: (Math.min(...ys) + Math.max(...ys)) / 2 };
}

function overlaps(a, b) {
  const sa = graphNodeSize(a), sb = graphNodeSize(b);
  return Math.abs(a.x - b.x) < (sa.width + sb.width) / 2 && Math.abs(a.y - b.y) < (sa.height + sb.height) / 2;
}

test("Square on a selection arranges only the selected nodes, around where they were", async () => {
  const selected = ["s1", "s2", "s3", "s4"];
  const graph = {
    revision: 1,
    nodes: [node("s1", 2000, 1900), node("s2", 2600, 2050), node("s3", 2100, 2400), node("s4", 2500, 2300), node("o1", 0, 0), node("o2", 0, 300, { pinned: true })],
    edges: [edge("s1", "s2"), edge("s2", "o1"), edge("o1", "o2"), edge("s3", "s4")],
  };
  const before = new Map(graph.nodes.map((n) => [n.id, { x: n.x, y: n.y }]));
  const { positions } = await computeGraphLayout(graph, { mode: "square", localNodeIds: new Set(selected) });
  assert.deepEqual(positions.get("o1"), { x: 0, y: 0 });
  assert.deepEqual(positions.get("o2"), { x: 0, y: 300 });
  assert.equal(new Set(selected.map((id) => positions.get(id).x)).size, 2, "two columns");
  assert.equal(new Set(selected.map((id) => positions.get(id).y)).size, 2, "two rows");
  const was = centre(before, selected), is = centre(positions, selected);
  assert.ok(Math.abs(was.x - is.x) < 1e-6 && Math.abs(was.y - is.y) < 1e-6, "the block stays centred where the selection was");
});

test("Hierarchy on a selection ranks only the selected nodes and ignores links leaving it", async () => {
  const graph = {
    revision: 1,
    nodes: [node("root", 900, 900), node("left", 700, 1200), node("right", 1100, 1100), node("outside", 0, 0)],
    edges: [edge("root", "left"), edge("root", "right"), edge("outside", "root")],
  };
  const { positions } = await computeGraphLayout(graph, { mode: "hierarchy", localNodeIds: new Set(["root", "left", "right"]) });
  assert.deepEqual(positions.get("outside"), { x: 0, y: 0 });
  assert.equal(positions.get("left").y, positions.get("right").y, "the children share a rank");
  assert.ok(positions.get("root").y < positions.get("left").y, "the root ranks above its children");
});

test("a block that would land on a fixed node moves whole, without being deformed", async () => {
  const selected = ["s1", "s2", "s3", "s4"];
  const graph = {
    revision: 1,
    // The selection surrounds a node that is not selected.
    nodes: [node("s1", -300, -200), node("s2", 300, -200), node("s3", -300, 200), node("s4", 300, 200), node("middle", 0, 0)],
    edges: [],
  };
  const { positions } = await computeGraphLayout(graph, { mode: "square", localNodeIds: new Set(selected) });
  assert.deepEqual(positions.get("middle"), { x: 0, y: 0 });
  const middle = { ...graph.nodes[4] };
  for (const id of selected) assert.ok(!overlaps({ ...graph.nodes.find((n) => n.id === id), ...positions.get(id) }, middle), `${id} clears the fixed node`);
  const grid = computeSquareLayout({ ...graph, nodes: graph.nodes.slice(0, 4) });
  const dx = positions.get("s1").x - grid.get("s1").x, dy = positions.get("s1").y - grid.get("s1").y;
  for (const id of selected) {
    assert.ok(Math.abs(positions.get(id).x - grid.get(id).x - dx) < 1e-6 && Math.abs(positions.get(id).y - grid.get(id).y - dy) < 1e-6, `${id} keeps its place in the grid`);
  }
});

test("a Square of the whole graph leaves pinned nodes where they are", async () => {
  const graph = {
    revision: 1,
    nodes: [node("a", 0, 0), node("b", 50, 400), node("c", 900, 30), node("d", 800, 700), node("pin", 5000, 5000, { pinned: true })],
    edges: [edge("a", "b"), edge("c", "pin")],
  };
  const { positions } = await computeGraphLayout(graph, { mode: "square" });
  assert.deepEqual(positions.get("pin"), { x: 5000, y: 5000 });
  assert.equal(new Set(["a", "b", "c", "d"].map((id) => positions.get(id).y)).size, 2);
});
